export default function (input) {
  const now = new Date(input.now);
  const lagos = new Date((isNaN(now.getTime()) ? new Date() : now).getTime() + 3600 * 1000);
  return { date: lagos.toISOString().slice(0, 10) };
}

function naira(n) { return 'NGN ' + Number(n).toLocaleString('en-NG', { minimumFractionDigits: 0, maximumFractionDigits: 2 }); }
function latestByReference(rows) {
  const by = {};
  for (const r of rows || []) {
    if (!r || !r.reference) continue;
    const seen = by[r.reference];
    if (!seen || String(r.happened_at || '') >= String(seen.happened_at || '')) by[r.reference] = r;
  }
  return Object.keys(by).map(function (k) { return by[k]; });
}
function nameOf(terminals, serial) {
  for (const t of terminals || []) if (t && String(t.serial) === String(serial)) return t.name ? String(t.name) : String(serial);
  return String(serial || 'unknown terminal');
}
export default function (input) {
  const sales = latestByReference(input.rows);
  const perTerminal = {}, perKind = {};
  let total = 0, count = 0, declined = 0, biggest = 0;
  for (const s of sales) {
    if (!s.approved) { if (String(s.status) !== 'pending') declined += 1; continue; }
    const a = Number(s.amount); if (!isFinite(a)) continue;
    total += a; count += 1; if (a > biggest) biggest = a;
    const t = nameOf(input.terminals, s.terminal);
    perTerminal[t] = perTerminal[t] || { total: 0, count: 0 }; perTerminal[t].total += a; perTerminal[t].count += 1;
    const k = String(s.kind || 'other');
    perKind[k] = perKind[k] || { total: 0, count: 0 }; perKind[k].total += a; perKind[k].count += 1;
  }
  const lines = [input.business_name + ' POS, ' + input.date + ': ' + count + ' sale(s), ' + naira(total) + '.'];
  const terminals = Object.keys(perTerminal).sort();
  if (terminals.length > 1) for (const t of terminals) lines.push(t + ': ' + perTerminal[t].count + ' sale(s), ' + naira(perTerminal[t].total));
  const kinds = Object.keys(perKind).sort();
  if (kinds.length > 1) lines.push('By kind: ' + kinds.map(function (k) { return k + ' ' + naira(perKind[k].total); }).join(', ') + '.');
  if (biggest > 0 && count > 1) lines.push('Biggest sale: ' + naira(biggest) + '.');
  if (declined > 0) lines.push(declined + ' payment(s) did not go through.');
  if (count === 0) lines[0] = input.business_name + ' POS, ' + input.date + ': no sales recorded today.';
  return { total: Math.round(total * 100) / 100, count: count, declined: declined, message: lines.join('\n') };
}
